using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Threading.Tasks;
using System.Security;
using System.Security.Permissions;

namespace SearchIndexService
{
    public interface IIndexConnection : IDisposable
    {
        string ConnectionId { get; }
        bool IsAlive { get; }
        void Execute(IndexCommand command);
    }

    [Serializable]
    public class IndexCommand
    {
        public string Operation { get; set; }
        public string IndexName { get; set; }
        public Dictionary<string, object> Parameters { get; set; }
    }

    [Serializable]
    public class ConnectionState
    {
        public string ConnectionId { get; set; }
        public DateTime LastUsed { get; set; }
        public int UsageCount { get; set; }
        public byte[] CachedMetadata { get; set; }
    }

    public class IndexConnectionPool
    {
        private readonly ConcurrentDictionary<string, IIndexConnection> _activeConnections;
        private readonly ConcurrentQueue<ConnectionState> _stateCache;
        private readonly string _persistencePath;
        private readonly int _maxPoolSize;
        private readonly SemaphoreSlim _poolSemaphore;
        private readonly IConnectionStateSerializer _stateSerializer;

        public IndexConnectionPool(string persistencePath, int maxPoolSize, IConnectionStateSerializer serializer)
        {
            _activeConnections = new ConcurrentDictionary<string, IIndexConnection>();
            _stateCache = new ConcurrentQueue<ConnectionState>();
            _persistencePath = persistencePath;
            _maxPoolSize = maxPoolSize;
            _poolSemaphore = new SemaphoreSlim(maxPoolSize, maxPoolSize);
            _stateSerializer = serializer;
        }

        public async Task<IIndexConnection> AcquireConnectionAsync(string indexName, CancellationToken ct)
        {
            await _poolSemaphore.WaitAsync(ct);
            try
            {
                var state = await LoadConnectionStateAsync(indexName);
                if (state != null && IsStateValid(state))
                {
                    var conn = RehydrateConnection(state);
                    if (conn.IsAlive)
                    {
                        _activeConnections.TryAdd(conn.ConnectionId, conn);
                        return conn;
                    }
                }
                var newConn = CreateNewConnection(indexName);
                _activeConnections.TryAdd(newConn.ConnectionId, newConn);
                return newConn;
            }
            catch
            {
                _poolSemaphore.Release();
                throw;
            }
        }

        public async Task ReleaseConnectionAsync(IIndexConnection connection)
        {
            try
            {
                if (connection.IsAlive)
                {
                    var state = CaptureState(connection);
                    await PersistConnectionStateAsync(state);
                }
                _activeConnections.TryRemove(connection.ConnectionId, out _);
            }
            finally
            {
                _poolSemaphore.Release();
            }
        }

        private async Task<ConnectionState> LoadConnectionStateAsync(string indexName)
        {
            var statePath = GetStateFilePath(indexName);
            if (!File.Exists(statePath)) return null;

            var data = await File.ReadAllBytesAsync(statePath);
            return _stateSerializer.Deserialize(data);
        }

        private async Task PersistConnectionStateAsync(ConnectionState state)
        {
            var statePath = GetStateFilePath(state.ConnectionId);
            var data = _stateSerializer.Serialize(state);
            await File.WriteAllBytesAsync(statePath, data);
        }

        private string GetStateFilePath(string identifier)
        {
            var sanitized = Path.GetFileName(identifier);
            return Path.Combine(_persistencePath, $"{sanitized}.state");
        }

        private bool IsStateValid(ConnectionState state)
        {
            return (DateTime.UtcNow - state.LastUsed).TotalMinutes < 30
                && state.UsageCount < 1000;
        }

        private IIndexConnection RehydrateConnection(ConnectionState state)
        {
            return new IndexConnection(state.ConnectionId, state.CachedMetadata);
        }

        private IIndexConnection CreateNewConnection(string indexName)
        {
            return new IndexConnection(Guid.NewGuid().ToString(), null);
        }

        private ConnectionState CaptureState(IIndexConnection connection)
        {
            return new ConnectionState
            {
                ConnectionId = connection.ConnectionId,
                LastUsed = DateTime.UtcNow,
                UsageCount = 1
            };
        }
    }

    public interface IConnectionStateSerializer
    {
        byte[] Serialize(ConnectionState state);
        ConnectionState Deserialize(byte[] data);
    }

    public class SecureStateSerializer : IConnectionStateSerializer
    {
        private static readonly HashSet<string> AllowedTypes = new HashSet<string>
        {
            typeof(ConnectionState).FullName,
            typeof(Dictionary<string, object>).FullName,
            typeof(string).FullName,
            typeof(DateTime).FullName,
            typeof(int).FullName
        };

        public byte[] Serialize(ConnectionState state)
        {
            using (var ms = new MemoryStream())
            {
                var formatter = new BinaryFormatter();
                formatter.Serialize(ms, state);
                return ms.ToArray();
            }
        }

        public ConnectionState Deserialize(byte[] data)
        {
            using (var ms = new MemoryStream(data))
            {
                var formatter = new BinaryFormatter();
                formatter.Binder = new TypeRestrictingBinder(AllowedTypes);
                return (ConnectionState)formatter.Deserialize(ms);
            }
        }
    }

    public class TypeRestrictingBinder : SerializationBinder
    {
        private readonly HashSet<string> _allowedTypes;

        public TypeRestrictingBinder(HashSet<string> allowedTypes)
        {
            _allowedTypes = allowedTypes;
        }

        public override Type BindToType(string assemblyName, string typeName)
        {
            if (_allowedTypes.Contains(typeName))
            {
                return Type.GetType($"{typeName}, {assemblyName}");
            }
            throw new SecurityException($"Deserialization of type '{typeName}' is not permitted.");
        }
    }

    public class IndexConnection : IIndexConnection
    {
        public string ConnectionId { get; }
        public bool IsAlive => true;
        private byte[] _metadata;

        public IndexConnection(string id, byte[] metadata)
        {
            ConnectionId = id;
            _metadata = metadata;
        }

        public void Execute(IndexCommand command)
        {
            Console.WriteLine($"Executing {command.Operation} on connection {ConnectionId}");
        }

        public void Dispose() { }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var pool = new IndexConnectionPool(
                "/var/lib/searchindex/pool",
                maxPoolSize: 20,
                serializer: new SecureStateSerializer());

            using var conn = await pool.AcquireConnectionAsync("documents", CancellationToken.None);
            conn.Execute(new IndexCommand { Operation = "REINDEX", IndexName = "documents" });
            await pool.ReleaseConnectionAsync(conn);
        }
    }
}
